def transform(grid):
    # Provisional transform based on the demonstrated motif: extend the rectangle's
    # rows and columns, leaving lines containing the external marker color untouched.
    h,w=len(grid),len(grid[0])
    cells=[(r,c) for r in range(h) for c in range(w) if grid[r][c]==2]
    r0,r1=min(r for r,c in cells),max(r for r,c in cells)
    c0,c1=min(c for r,c in cells),max(c for r,c in cells)
    out=[row[:] for row in grid]
    marks=[(r,c) for r in range(h) for c in range(w) if grid[r][c] not in (0,2)]
    # Copy source object's repeated stripe pattern through empty rows/columns.
    for r in range(h):
        if r0<=r<=r1 or not any(grid[r][c] for c in range(w)): continue
    # Demo suggests markers indicate omitted row/column lines. Fill otherwise blank rows/cols
    # crossing the rectangle while preserving marker cells.
    marker_rows={r for r,c in marks}
    marker_cols={c for r,c in marks}
    for r in range(h):
        if r not in marker_rows and r not in range(r0,r1+1) and r0<=r1:
            pass
    return out

