{
 "path": "programs/task-de566c57.py",
 "content": "def transform(grid):
    h,w=len(grid),len(grid[0])
    pts=[(r,c) for r in range(h) for c in range(w) if grid[r][c]==2]
    r0,r1=min(r for r,c in pts),max(r for r,c in pts)
    c0,c1=min(c for r,c in pts),max(c for r,c in pts)
    out=[row[:] for row in grid]
    markers=[(r,c) for r in range(h) for c in range(w) if grid[r][c]==1]
    # External markers specify locations of rays; each ray color-2 projection aligns
    # with its row or column and continues through the canvas, except marker positions.
    marker_rows={r for r,c in markers if c<c0 or c>c1}
    marker_cols={c for r,c in markers if r<r0 or r>r1}
    # Rectangle expands as horizontal bands for unmarked rows and vertical bands for
    # unmarked columns; retain the given marker on every line.
    for r in range(h):
        if r not in marker_rows and (r0<=r<=r1):
            for c in range(w):
                if out[r][c]==0: out[r][c]=2
    for c in range(w):
        if c not in marker_cols and (c0<=c<=c1):
            for r in range(h):
                if out[r][c]==0: out[r][c]=2
    return out
"
}

