{
 "path": "programs/task-de566c57.py",
 "content": "def transform(grid):
    h,w=len(grid),len(grid[0])
    loc=[(r,c) for r in range(h) for c in range(w) if grid[r][c]==2]
    r0,r1=min(r for r,c in loc),max(r for r,c in loc)
    c0,c1=min(c for r,c in loc),max(c for r,c in loc)
    out=[row[:] for row in grid]
    markers=[(r,c) for r in range(h) for c in range(w) if grid[r][c] not in (0,2)]
    # The marker layout defines parallel ray lanes around the rectangle. In examples,
    # rows intersecting external markers are not extended; remaining rectangle rows extend
    # sideways, and columns similarly extend vertically, preserving marker cells.
    mr={r for r,c in markers if c<c0 or c>c1}
    mc={c for r,c in markers if r<r0 or r>r1}
    for r in range(r0,r1+1):
        if r not in mr:
            for c in range(w):
                if out[r][c]==0: out[r][c]=2
